.dm-agx-now i{grid-column:2;grid-row:1;position:relative;z-index:1}
@keyframes dm-agnow{50%{opacity:.4}}
@media (prefers-reduced-motion:reduce){.dm-agx-now i{animation:none}}
.dm-agx-join{margin-top:var(--dm-s-2);align-self:flex-start}
